function Footer() {
  return <footer className="border-t border-slate-700/70 bg-[#0B1120] text-slate-300">
    <div className="mx-auto grid max-w-[1440px] gap-10 px-5 py-14 sm:grid-cols-2 lg:grid-cols-[1.5fr_1fr_1fr_1fr] lg:px-10">
      <div><Brand /><p className="mt-5 max-w-xs text-sm leading-6 text-slate-400">A controlled institutional exchange for enterprise opportunities, assets and strategic capital.</p><p className="mt-8 text-xs text-slate-500">© 2025 Fathom Services</p></div>
      <FooterGroup title="Exchange" links={[['Explore opportunities', '/tenders'], ['Submit mandate', '/procurement'], ['How it works', '/manual']]} />
      <FooterGroup title="Fathom" links={[['About Fathom', '/about'], ['Client profile', '/profile'], ['Sign in', '/login']]} />
      <FooterGroup title="Governance" links={[['Privacy policy', '/legal/privacy'], ['Terms of exchange', '/legal/terms'], ['Security principles', '/about#security']]} />
    </div>
  </footer>;
}

function FooterGroup({ title, links }: { title: string; links: string[][] }) {
  return <div><h3 className="mb-4 text-[10px] font-bold uppercase tracking-[.2em] text-[#CA8A04]">{title}</h3>{links.map(([label, href]) => <Link key={label} href={href} className="mb-3 block text-sm text-slate-400 transition-colors hover:text-slate-100" data-testid={`link-footer-${label.toLowerCase().replaceAll(' ', '-')}`}>{label}</Link>)}</div>;
}

function BackToTop() {
  const [visible, setVisible] = useState(false);
  useEffect(() => {
    const onScroll = () => setVisible(window.scrollY > 420);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);
  if (!visible) return null;
  return <button onClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })} className="scroll-top fixed bottom-6 right-5 z-30 flex h-10 w-10 items-center justify-center rounded-full border border-[#CA8A04]/60 bg-[#1E293B] text-[#EAB308] shadow-xl transition-colors hover:bg-[#334155]" aria-label="Back to top" data-testid="button-back-to-top"><ChevronUp size={18} /></button>;
}

function PageShell({ children }: { children: ReactNode }) {
  return <div className="min-h-[100dvh] bg-[#0F172A] text-slate-200 noise"><Header />{children}<Footer /><BackToTop /></div>;
}

function SectionIntro({ eyebrow, title, copy, dark = false }: { eyebrow: string; title: string; copy?: string; dark?: boolean }) {
  return <div className="mb-10 max-w-2xl"><div className="mb-4 flex items-center gap-3 text-[10px] font-bold uppercase tracking-[.2em] text-[#CA8A04]"><span className="h-px w-7 bg-[#CA8A04]" />{eyebrow}</div><h2 className={`font-display text-3xl font-bold leading-tight tracking-[-.03em] sm:text-4xl ${dark ? 'text-slate-100' : 'text-slate-100'}`}>{title}</h2>{copy && <p className="mt-4 max-w-xl text-base leading-7 text-slate-400">{copy}</p>}</div>;
}

